<?php
declare(strict_types=1);
function home_page(): void {
 if(current_user())go('dashboard');
 require ROOT.'/app/landing.php';
}
function service_card(array $s): void { ?><article class="service-card"><div class="flex between"><span class="service-icon"><?=icon($s['kind']==='permit'?'file':'chat')?></span><?=badge($s['kind'])?></div><span class="service-dept"><?=e($s['department_name'])?></span><h3><?=e($s['title'])?></h3><p><?=e($s['description'])?></p><div class="service-meta"><span><?=icon('clock')?> <?=(int)$s['sla_hours']?> hour target</span><span><?=$s['fee']>0?'₦'.number_format((float)$s['fee']).(cfg('demo_mode',false)?' sample fee':' published fee'):'No fee'?></span></div><a class="btn btn-outline btn-sm" href="<?=e(url('services/'.$s['id']))?>">View requirements <?=icon('arrow')?></a></article><?php }
function auth_page(string $path): void {
 if(current_user()&&in_array($path,['/login','/register'],true))go('dashboard');$title=match($path){'/register'=>'Create your citizen account','/forgot-password'=>'Reset your password','/reset-password'=>'Choose a new password',default=>'Sign in'};page_start($title,'Enter your account details to continue.');
 ?><div class="auth-wrap"><section class="panel"><div class="panel-body"><div class="auth-intro"><h2><?=e($title)?></h2><p><?= $path==='/login'?'Sign in to follow your requests or manage services.':'Complete the required account information.'?></p></div><form method="post" action="<?=e(url(ltrim($path,'/')))?>" data-once><?=csrf_field()?><?php if($path==='/register'){field('name','Full name','','text','required maxlength="140" autocomplete="name"');field('phone','Phone number','','tel','required maxlength="25" autocomplete="tel"');}if($path!=='/reset-password')field('email','Email address','','email','required maxlength="190" autocomplete="email"');
 if($path!=='/forgot-password'){field('password',$path==='/reset-password'?'New password':'Password','','password','required '.($path==='/login'?'autocomplete="current-password"':'minlength="12" maxlength="72" autocomplete="new-password"'));}
 if(in_array($path,['/register','/reset-password'],true)){field('password_confirm','Confirm password','','password','required minlength="12" maxlength="72" autocomplete="new-password"');echo '<p class="small muted">Use at least 12 characters, including letters and numbers.</p>';}
 if($path==='/reset-password'){echo '<input type="hidden" name="token" value="'.e($_GET['token']??'').'">';}
 if($path==='/register'):?><label class="checkbox"><input type="checkbox" name="consent" value="1" required><span>I have read the <a href="<?=e(url('privacy'))?>">privacy notice</a> and agree to use this service portal responsibly.</span></label><?php endif;?><button class="btn btn-primary" type="submit"><?=e(match($path){'/register'=>'Create account','/forgot-password'=>'Send reset instructions','/reset-password'=>'Save new password',default=>'Sign in'})?> <?=icon('arrow')?></button></form><hr class="divider"><div class="small"><?php if($path==='/login'):?><div class="flex between"><a href="<?=e(url('register'))?>">Create a citizen account</a><a href="<?=e(url('forgot-password'))?>">Forgot password?</a></div><?php else:?><a href="<?=e(url('login'))?>">Return to sign in</a><?php endif;?></div></div></section></div><?php page_end();
}
function services_page(): void {
 $kind=(string)($_GET['kind']??'');$dept=(int)($_GET['department']??0);$q=mb_substr(trim((string)($_GET['q']??'')),0,100);$list=service_list();$list=array_values(array_filter($list,fn($s)=>(!in_array($kind,['complaint','permit'],true)||$s['kind']===$kind)&&(!$dept||(int)$s['department_id']===$dept)&&($q===''||mb_stripos($s['title'].' '.$s['description'].' '.$s['department_name'],$q)!==false)));
 page_start('Service directory','Find the right service and know what to prepare.','services');?><form class="filters" method="get" action="<?=e(url('services'))?>"><?php field('q','Search services',$q,'search','placeholder="Service, issue or department"');select_field('kind','Service type',[''=>'All services','complaint'=>'Complaints','permit'=>'Permits and licences'],$kind);$opts=[''=>'All departments'];foreach(rows('SELECT id,name FROM departments ORDER BY name')as $d)$opts[$d['id']]=$d['name'];select_field('department','Department',$opts,(string)$dept);?><button class="btn btn-primary" type="submit"><?=icon('search')?> Find services</button></form><div class="section-heading"><h2><?=count($list)?> services available</h2><a href="<?=e(url('assistant'))?>">Need help choosing?</a></div><?php if($list):?><div class="grid grid-3"><?php foreach($list as $s)service_card($s);?></div><?php else:empty_state('No matching services','Try another search or clear your filters.','services','Show all services');endif;page_end();
}
function service_page(int $id): void {
 $s=row('SELECT s.*,d.name department_name FROM services s JOIN departments d ON d.id=s.department_id WHERE s.id=? AND s.active=1',[$id]);if(!$s)abort_page(404,'Service not found.');page_start($s['title'],$s['department_name'],'services');?><div class="detail-grid"><div class="stack"><section class="hero-panel"><span class="eyebrow"><?=e($s['department_name'])?></span><h2><?=e($s['title'])?></h2><p><?=e($s['description'])?></p><a class="btn btn-light" href="<?=e(url(current_user()&&!can('requests.create')?'dashboard':'requests/new?service='.$id))?>"><?=current_user()&&!can('requests.create')?'Open workspace':'Start request'?> <?=icon('arrow')?></a></section><?php panel_start('What to prepare');?><p class="prose"><?=e($s['requirements']?:'A clear description of your request and where it relates to.')?></p><p class="small muted">Documents: PDF, JPG and PNG. Up to 5 MB per file and three files per upload. You can add further evidence in the request conversation.</p><?php panel_end();?></div><section class="panel panel-body"><h3>Service details</h3><dl class="detail-meta"><div><dt>Type</dt><dd><?=e(label($s['kind']))?></dd></div><div><dt>Target time</dt><dd><?=(int)$s['sla_hours']?> calendar hours</dd></div><div><dt>Published fee</dt><dd><?=$s['fee']>0?'₦'.number_format((float)$s['fee'],2):'No fee'?></dd></div><div><dt>Department</dt><dd><?=e($s['department_name'])?></dd></div></dl><hr class="divider"><p class="small muted">Service targets and charges are set by the responsible authority. Payments are not collected here. Contact the appropriate emergency service for emergencies.</p><a class="btn btn-outline" href="<?=e(url('assistant'))?>"><?=icon('chat')?> Ask the assistant</a></section></div><?php page_end();
}
function track_page(): void {
 page_start('Track a request','A clear view of progress, without another queue.','track');$r=null;$t=$_SESSION['public_track']??[];if(($t['expires']??0)>time())$r=row('SELECT r.*,s.title service_title,d.name department_name FROM requests r JOIN services s ON s.id=r.service_id JOIN departments d ON d.id=r.department_id WHERE r.id=?',[$t['id']]);
 ?><div class="grid grid-2"><form class="panel panel-body" action="<?=e(url('track'))?>" method="post"><?=csrf_field()?><h2>Enter your tracking details</h2><p class="small muted">Use the reference and private code on your request receipt. Signed-in citizens can view complete records from My requests.</p><?php field('reference','Request reference','','text','required maxlength="50" placeholder="GOV-CMP-2026-…" autocomplete="off"');field('tracking_code','Private tracking code','','password','required maxlength="64" autocomplete="off"');?><button class="btn btn-primary" type="submit">Track request <?=icon('arrow')?></button></form><div class="stack"><?php if($r):panel_start('Request progress');?><p class="mono"><?=e($r['reference'])?></p><h3><?=e($r['service_title'])?></h3><p><?=badge($r['status'])?> <?=$r['escalated_at']?'<span class="badge status-high">Escalated</span>':''?></p><dl class="detail-meta"><div><dt>Department</dt><dd><?=e($r['department_name'])?></dd></div><div><dt>Target</dt><dd><?=e(dates($r['due_at'],true))?></dd></div></dl><hr class="divider"><ol class="timeline"><?php foreach(rows("SELECT * FROM events WHERE request_id=? AND visibility='public' AND from_status<>to_status ORDER BY id DESC",[$r['id']])as $ev):?><li><strong><?=e(label($ev['to_status']))?></strong><small><?=e(dates($ev['created_at'],true))?></small></li><?php endforeach;?></ol><p class="small muted mt">For documents and messages, sign in to the owner account. Tracking access expires after 10 minutes.</p><?php panel_end();else:?><section class="panel panel-body"><span class="service-icon"><?=icon('shield')?></span><h3>Your tracking code is private</h3><p class="small muted">A reference identifies the request. The private code confirms access to its progress. Personal details and attachments are available only inside the signed-in account.</p><a href="<?=e(url('requests'))?>" class="btn btn-outline">Open my requests</a></section><?php endif;?></div></div><?php page_end();
}
function assistant_page(): void {
 $live=setting('ai_enabled','0')==='1'&&secret('ai_api_key')!==''&&setting('ai_model')!=='';page_start('Citizen assistant','Guidance for the next step in your service request.','assistant');?><div class="chat-wrap"><section class="panel"><div class="panel-header"><h2><?=icon('chat')?> How can I help?</h2><span class="small" id="chatStatus" role="status"><?=$live?'AI assistance available':'Service guide ready'?></span></div><div class="panel-body"><div class="chat-log" id="chatLog" aria-live="polite" aria-label="Assistant conversation"><div class="chat-message assistant"><strong><?=$live?'Citizen assistant':'Service guide'?></strong><p>Hello. I can help you choose a service, prepare an application or find out how to track a request. What would you like to do?</p></div></div><form action="<?=e(url('api/assistant'))?>" method="post" id="assistantForm"><div class="chat-compose"><input name="question" aria-label="Your question" maxlength="1500" required placeholder="Ask about complaints, permits or tracking…"><button class="btn btn-primary" type="submit">Send <?=icon('arrow')?></button></div><?php if($live):?><label class="checkbox"><input type="checkbox" name="use_ai" value="1" checked> Use AI assistance. Your question will be sent to the configured AI provider. Uncheck to use the local service guide.</label><?php endif;?></form><div class="suggestions"><?php foreach(['How do I apply for a permit?','How do I track my request?','What documents can I upload?']as $s):?><button type="button" data-question="<?=e($s)?>"><?=e($s)?></button><?php endforeach;?></div><p class="small muted mt">Do not include passwords, identity numbers or private documents. For your individual case, use the message thread on your request. The assistant provides guidance and cannot approve applications.</p><noscript><p>JavaScript is needed for the chat. The <a href="<?=e(url('help'))?>">Help centre</a> contains the same service guidance.</p></noscript></div></section></div><?php page_end();
}
function help_page(): void {page_start('Help centre','Answers that keep your service request moving.','help');?><div class="detail-grid"><section><?php foreach(rows('SELECT * FROM faqs WHERE active=1 ORDER BY id')as $f):?><details id="faq-<?=(int)$f['id']?>"><summary><?=e($f['question'])?></summary><p class="prose"><?=e($f['answer'])?></p></details><?php endforeach;?></section><section class="panel panel-body"><span class="service-icon"><?=icon('chat')?></span><h3>Need help with an existing case?</h3><p class="small muted">Open your request and use its conversation to contact the responsible department. Include the detail requested by the officer and attach supporting evidence when useful.</p><div class="actions"><a class="btn btn-primary" href="<?=e(url('requests'))?>">My requests</a><a class="btn btn-outline" href="<?=e(url('assistant'))?>">Ask the assistant</a></div></section></div><?php page_end();}
function privacy_page(): void {page_start('Privacy and data use','Understand what is stored and who can see it.');?><div class="panel panel-body"><h2>Your request information</h2><p class="small">CivicFlow stores your name, email, phone, account preferences, service requests, submitted documents, status history and feedback. Account credentials are stored as password hashes. Staff actions and access-related events are recorded for accountability.</p><h3>Access and sharing</h3><p class="small">Citizens see their own records. Officers see requests routed to their department. Administrators manage services and accounts and oversee requests. Attachments are stored outside public access and delivered only after a permission check. The private tracking code provides limited progress access; keep it confidential.</p><h3>Notifications and AI</h3><p class="small">Email and SMS are optional delivery channels configured by the administrator. Delivery providers receive the recipient and message needed to send an update. Profile preferences control routine email and SMS updates; requested password resets use email. If enabled, AI assistance sends the question and public service information to the configured provider. Questions are not automatically supplied with private request records or account details. Use the local guide if you do not want AI processing.</p><h3>Responsible use and retention</h3><p class="small">Do not upload passwords, payment credentials or unnecessary identity documents. Records are retained according to the operating organisation’s service and recordkeeping policy. The operator manages removal and protected backups. Contact the portal operator using the published support email for account or record removal. Backups and exported reports must be protected by the operator.</p><h3>Deployment responsibility</h3><p class="small">The portal operator is responsible for its published service authority, retention policy, support contact and applicable privacy obligations. The software does not by itself certify legal compliance or government endorsement.</p></div><?php page_end();}
function about_page(): void {
 page_start('About CivicFlow','Public services with clear progress.','about');panel_start('A connected service workspace');?><p class="small">CivicFlow connects citizens and service departments through online complaints, permit applications, document submission and a shared record of progress. Requests are routed to the appropriate department, reviewed by authorised staff and tracked through to a recorded outcome.</p><h3>Service operator</h3><p class="small"><?=e(setting('organisation_name','CivicFlow'))?></p><?php if(setting('support_email')):?><p class="small">Support: <a href="mailto:<?=e(setting('support_email'))?>"><?=e(setting('support_email'))?></a></p><?php endif;?><h3>What you can do</h3><ul class="checklist"><li>Create an account and keep your service records together.</li><li>Submit complaints and permit applications with private documents.</li><li>Follow status updates and respond to requests for more information.</li><li>Receive configured notifications and rate completed services.</li></ul><h3>Accountability</h3><p class="small">Role permissions control the actions available to each staff member. Department scope limits access to case records. Decisions, messages, assignments and administrative changes are recorded in the audit trail.</p><?php if(cfg('demo_mode',false)):?><div class="notice">Project data information: prepared example records are fictional and for evaluation only. Project approval documents have no legal effect.</div><?php endif;panel_end();page_end();
}
function verify_page(string $reference): void {
 $r=row("SELECT r.reference,r.status,r.closed_at,s.title service_title,d.name department_name FROM requests r JOIN services s ON s.id=r.service_id JOIN departments d ON d.id=r.department_id WHERE r.reference=? AND r.kind='permit'",[$reference]);page_start('Approval verification','Check an approval recorded in this workspace.');panel_start('Verification result');if(!$r||$r['status']!=='approved'){empty_state('No valid approval found','The reference does not identify an approved permit in this workspace.');}else{?><span class="service-icon"><?=icon('check')?></span><h2>Approval record found</h2><dl class="detail-meta"><div><dt>Reference</dt><dd><?=e($r['reference'])?></dd></div><div><dt>Service</dt><dd><?=e($r['service_title'])?></dd></div><div><dt>Department</dt><dd><?=e($r['department_name'])?></dd></div><div><dt>Decision date</dt><dd><?=e(dates($r['closed_at'],true))?></dd></div></dl><p class="notice mt"><?=cfg('demo_mode',false)?'This confirms a demonstration record and has no legal effect.':'This confirms the approval record held by '.e(setting('organisation_name','the issuing organisation')).'. Contact the issuing authority to confirm the applicable conditions.'?> Applicant details remain private.</p><?php }panel_end();page_end();
}

function verify_email_page(): void {
 page_start('Verify your email','Confirm the address used for service notifications.');?><div class="auth-wrap panel panel-body"><h2>Confirm your email address</h2><p class="small muted">Continue to verify the email address linked to this verification message. This link expires after 24 hours.</p><form method="post" action="<?=e(url('verify-email'))?>"><?=csrf_field()?><input type="hidden" name="token" value="<?=e($_GET['token']??'')?>"><button class="btn btn-primary" type="submit">Verify email address</button></form></div><?php page_end();
}
